BEGIN;
CREATE TABLE public.maintenance_finance_invoices (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),order_id uuid NOT NULL,partner_id uuid NOT NULL,request_id uuid NOT NULL,numero text NOT NULL CHECK(length(btrim(numero)) BETWEEN 1 AND 60),serie text NOT NULL DEFAULT '' CHECK(length(serie)<=20),chave_acesso text NOT NULL DEFAULT '' CHECK(length(chave_acesso)<=100),emissao date NOT NULL,valor numeric(14,2) NOT NULL CHECK(valor>0),observacao text NOT NULL DEFAULT '' CHECK(length(observacao)<=2000),status text NOT NULL DEFAULT 'conferencia' CHECK(status IN ('conferencia','liberada','cancelada')),version integer NOT NULL DEFAULT 1,
 referencia_orcamento numeric(14,2),referencia_aprovacao timestamptz,referencia_faturado numeric(14,2),justificativa text NOT NULL DEFAULT '',conferido_por uuid REFERENCES auth.users(id),conferido_em timestamptz,motivo_cancelamento text,created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(id,company_id),UNIQUE(company_id,request_id),FOREIGN KEY(order_id,company_id) REFERENCES public.maintenance_orders(id,company_id),FOREIGN KEY(partner_id,company_id) REFERENCES public.maintenance_partners(id,company_id));
CREATE UNIQUE INDEX finance_invoice_document ON public.maintenance_finance_invoices(company_id,partner_id,lower(btrim(numero)),lower(btrim(serie))) WHERE status<>'cancelada';
CREATE UNIQUE INDEX finance_invoice_access_key ON public.maintenance_finance_invoices(company_id,lower(chave_acesso)) WHERE chave_acesso<>'' AND status<>'cancelada';
CREATE INDEX finance_invoice_order_fk ON public.maintenance_finance_invoices(order_id,company_id);CREATE INDEX finance_invoice_partner_fk ON public.maintenance_finance_invoices(partner_id,company_id);CREATE INDEX finance_invoice_creator ON public.maintenance_finance_invoices(created_by);CREATE INDEX finance_invoice_reviewer ON public.maintenance_finance_invoices(conferido_por);
CREATE TABLE public.maintenance_finance_installments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),invoice_id uuid NOT NULL,numero integer NOT NULL CHECK(numero BETWEEN 1 AND 120),vencimento date NOT NULL,valor numeric(14,2) NOT NULL CHECK(valor>0),UNIQUE(invoice_id,numero),UNIQUE(id,company_id),FOREIGN KEY(invoice_id,company_id) REFERENCES public.maintenance_finance_invoices(id,company_id));
CREATE INDEX finance_installment_due ON public.maintenance_finance_installments(company_id,vencimento,id);CREATE INDEX finance_installment_invoice_fk ON public.maintenance_finance_installments(invoice_id,company_id);
CREATE TABLE public.maintenance_finance_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),installment_id uuid NOT NULL,request_id uuid NOT NULL,tipo text NOT NULL CHECK(tipo IN ('pagamento','estorno')),valor numeric(14,2) NOT NULL CHECK(valor>0),data_pagamento date NOT NULL,metodo text NOT NULL CHECK(metodo IN ('pix','boleto','transferencia','dinheiro','cartao','outro')),referencia text NOT NULL DEFAULT '' CHECK(length(referencia)<=120),observacao text NOT NULL DEFAULT '' CHECK(length(observacao)<=2000),reverses_id uuid UNIQUE,created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(id,company_id),UNIQUE(company_id,request_id),CHECK((tipo='estorno')=(reverses_id IS NOT NULL)),FOREIGN KEY(installment_id,company_id) REFERENCES public.maintenance_finance_installments(id,company_id),FOREIGN KEY(reverses_id,company_id) REFERENCES public.maintenance_finance_payments(id,company_id));
CREATE INDEX finance_payment_installment_fk ON public.maintenance_finance_payments(installment_id,company_id);CREATE INDEX finance_payment_reverse_fk ON public.maintenance_finance_payments(reverses_id,company_id);CREATE INDEX finance_payment_creator ON public.maintenance_finance_payments(created_by);CREATE INDEX finance_payment_date ON public.maintenance_finance_payments(company_id,data_pagamento);
CREATE TABLE public.maintenance_finance_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),invoice_id uuid NOT NULL,payment_id uuid,categoria text NOT NULL CHECK(categoria IN ('nota_fiscal','comprovante','outros')),object_path text NOT NULL UNIQUE,nome text NOT NULL,content_type text NOT NULL,tamanho_bytes bigint NOT NULL CHECK(tamanho_bytes BETWEEN 1 AND 20971520),created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(invoice_id,company_id) REFERENCES public.maintenance_finance_invoices(id,company_id),FOREIGN KEY(payment_id,company_id) REFERENCES public.maintenance_finance_payments(id,company_id));
CREATE INDEX finance_file_company ON public.maintenance_finance_files(company_id);
CREATE INDEX finance_file_invoice_fk ON public.maintenance_finance_files(invoice_id,company_id);CREATE INDEX finance_file_payment_fk ON public.maintenance_finance_files(payment_id,company_id);CREATE INDEX finance_file_creator ON public.maintenance_finance_files(created_by);
CREATE TABLE public.maintenance_finance_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),invoice_id uuid NOT NULL,action text NOT NULL,description text NOT NULL,details jsonb NOT NULL DEFAULT '{}',actor_id uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(invoice_id,company_id) REFERENCES public.maintenance_finance_invoices(id,company_id));
CREATE INDEX finance_audit_company ON public.maintenance_finance_audit(company_id);
CREATE INDEX finance_audit_invoice_fk ON public.maintenance_finance_audit(invoice_id,company_id,created_at);CREATE INDEX finance_audit_actor ON public.maintenance_finance_audit(actor_id);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['maintenance_finance_invoices','maintenance_finance_installments','maintenance_finance_payments','maintenance_finance_files','maintenance_finance_audit'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);EXECUTE format('CREATE POLICY company_read ON public.%I FOR SELECT TO authenticated USING(maintenance_private.partner_access(company_id))',t);END LOOP;END $$;
CREATE VIEW public.maintenance_finance_balances WITH(security_invoker=true) AS
WITH movements AS (SELECT company_id,installment_id,sum(CASE WHEN tipo='pagamento' THEN valor ELSE -valor END)::numeric(14,2) AS pago FROM public.maintenance_finance_payments GROUP BY company_id,installment_id),billed AS (SELECT company_id,order_id,sum(valor)::numeric(14,2) AS faturado FROM public.maintenance_finance_invoices WHERE status<>'cancelada' GROUP BY company_id,order_id)
SELECT b.id,b.company_id,b.invoice_id,i.order_id,i.partner_id,o.vehicle_id,o.numero AS numero_os,v.placa,coalesce(p.nome_fantasia,p.razao_social) AS oficina,i.numero AS nota_fiscal,i.serie,i.emissao,i.valor AS valor_nota,b.numero AS parcela,b.vencimento,b.valor,coalesce(m.pago,0)::numeric(14,2) AS pago,(b.valor-coalesce(m.pago,0))::numeric(14,2) AS saldo,i.status AS status_nota,i.version,o.valor_total AS orcamento,o.orcamento_status,o.aprovado_em,coalesce(f.faturado,0)::numeric(14,2) AS faturado_os,
(coalesce(f.faturado,0)>coalesce(o.valor_total,0)) AS acima_orcamento,
(i.status='liberada' AND o.orcamento_status='aprovado' AND o.status<>'cancelada' AND i.partner_id=o.partner_id AND i.referencia_orcamento IS NOT DISTINCT FROM o.valor_total AND i.referencia_aprovacao IS NOT DISTINCT FROM o.aprovado_em AND i.referencia_faturado IS NOT DISTINCT FROM f.faturado AND (f.faturado<=o.valor_total OR length(btrim(i.justificativa))>=5)) AS liberada_efetiva,
CASE WHEN i.status='cancelada' THEN 'cancelada' WHEN b.valor-coalesce(m.pago,0)<=0 THEN 'paga' WHEN b.vencimento<(now() AT TIME ZONE 'America/Sao_Paulo')::date THEN 'atrasada' WHEN coalesce(m.pago,0)>0 THEN 'parcial' ELSE 'aberta' END AS situacao
FROM public.maintenance_finance_installments b JOIN public.maintenance_finance_invoices i ON i.id=b.invoice_id AND i.company_id=b.company_id JOIN public.maintenance_orders o ON o.id=i.order_id AND o.company_id=i.company_id JOIN public.maintenance_partners p ON p.id=i.partner_id AND p.company_id=i.company_id JOIN public.veiculos v ON v.id=o.vehicle_id AND v.company_id=o.company_id LEFT JOIN movements m ON m.installment_id=b.id AND m.company_id=b.company_id LEFT JOIN billed f ON f.order_id=i.order_id AND f.company_id=i.company_id;
REVOKE ALL ON public.maintenance_finance_balances FROM PUBLIC,anon;GRANT SELECT ON public.maintenance_finance_balances TO authenticated;
CREATE FUNCTION maintenance_private.finance_storage_access(path text,writing boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.maintenance_finance_invoices i WHERE i.company_id::text=split_part(path,'/',1) AND i.id::text=split_part(path,'/',3) AND split_part(path,'/',2)='finance' AND split_part(path,'/',4)<>'' AND split_part(path,'/',5)='' AND maintenance_private.partner_access(i.company_id,writing) AND (NOT writing OR i.status<>'cancelada'));$$;
REVOKE ALL ON FUNCTION maintenance_private.finance_storage_access(text,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION maintenance_private.finance_storage_access(text,boolean) TO authenticated;
CREATE POLICY finance_storage_scope ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING(bucket_id<>'maintenance' OR split_part(name,'/',2)<>'finance' OR maintenance_private.finance_storage_access(name,false)) WITH CHECK(bucket_id<>'maintenance' OR split_part(name,'/',2)<>'finance' OR maintenance_private.finance_storage_access(name,true));
CREATE POLICY finance_storage_immutable ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(bucket_id<>'maintenance' OR split_part(name,'/',2)<>'finance') WITH CHECK(bucket_id<>'maintenance' OR split_part(name,'/',2)<>'finance');
CREATE POLICY finance_storage_references ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'maintenance' OR split_part(name,'/',2)<>'finance' OR NOT EXISTS(SELECT 1 FROM public.maintenance_finance_files f WHERE f.object_path=storage.objects.name));
CREATE FUNCTION maintenance_private.finance_amount(value text) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ BEGIN IF coalesce(value,'')!~'^[0-9]{1,12}([.][0-9]{1,2})?$' OR value::numeric<=0 THEN RAISE EXCEPTION 'Informe um valor positivo com até duas casas decimais.';END IF;RETURN value::numeric;END $$;
REVOKE ALL ON FUNCTION maintenance_private.finance_amount(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION maintenance_private.finance_event(c uuid,inv uuid,kind text,note text,data jsonb DEFAULT '{}') RETURNS void LANGUAGE sql SET search_path='' AS $$ INSERT INTO public.maintenance_finance_audit(company_id,invoice_id,action,description,details,actor_id) VALUES(c,inv,kind,note,data,auth.uid());$$;
REVOKE ALL ON FUNCTION maintenance_private.finance_event(uuid,uuid,text,text,jsonb) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION maintenance_private.finance_command(c uuid,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE inv public.maintenance_finance_invoices;o public.maintenance_orders;bill public.maintenance_finance_installments;payment public.maintenance_finance_payments;old_payment public.maintenance_finance_payments;file public.maintenance_finance_files;total numeric;paid numeric;amount numeric;selected uuid;entry jsonb;idx integer;plan_total numeric:=0;today date:=(now() AT TIME ZONE 'America/Sao_Paulo')::date;note text:=btrim(coalesce(b->>'observacao',''));page_number integer:=greatest(1,least(coalesce((b->>'page')::integer,1),100000));per_page integer:=CASE WHEN action='export' THEN 1000 ELSE 25 END;filters jsonb:=coalesce(b->'filters','{}');data jsonb;is_new boolean;
BEGIN
IF auth.uid() IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Sem acesso ao financeiro desta empresa.' USING ERRCODE='42501';END IF;
IF action NOT IN ('list','export','detail','options','order_summary') AND NOT maintenance_private.partner_access(c,true) THEN RAISE EXCEPTION 'Seu perfil permite somente consulta financeira.' USING ERRCODE='42501';END IF;
IF action='options' THEN RETURN jsonb_build_object('orders',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'numero',x.numero,'placa',x.placa,'vehicle_id',x.vehicle_id,'partner',x.partner,'partner_id',x.partner_id,'orcamento',x.valor_total,'orcamento_status',x.orcamento_status,'prazo_pagamento_dias',x.prazo_pagamento_dias) ORDER BY x.data_abertura DESC) FROM (SELECT ord.id,ord.numero,ord.vehicle_id,ord.partner_id,ord.valor_total,ord.orcamento_status,ord.data_abertura,veh.placa,coalesce(par.nome_fantasia,par.razao_social) AS partner,par.prazo_pagamento_dias FROM public.maintenance_orders ord JOIN public.veiculos veh ON veh.id=ord.vehicle_id JOIN public.maintenance_partners par ON par.id=ord.partner_id WHERE ord.company_id=c AND ord.status<>'cancelada') x),'[]'::jsonb));END IF;
IF action IN ('list','export') THEN
WITH rows AS (SELECT x.* FROM public.maintenance_finance_balances x WHERE x.company_id=c AND (coalesce(filters->>'order_id','')='' OR x.order_id=(filters->>'order_id')::uuid) AND (coalesce(filters->>'vehicle_id','')='' OR x.vehicle_id=(filters->>'vehicle_id')::uuid) AND (coalesce(filters->>'partner_id','')='' OR x.partner_id=(filters->>'partner_id')::uuid) AND (coalesce(filters->>'start','')='' OR x.vencimento>=(filters->>'start')::date) AND (coalesce(filters->>'end','')='' OR x.vencimento<=(filters->>'end')::date) AND (coalesce(filters->>'status','')='' AND x.status_nota<>'cancelada' OR filters->>'status'=x.situacao OR filters->>'status'='conferencia' AND NOT x.liberada_efetiva AND x.status_nota<>'cancelada' AND x.saldo>0) AND (coalesce(filters->>'search','')='' OR concat_ws(' ',x.numero_os,x.placa,x.oficina,x.nota_fiscal) ILIKE '%'||left(filters->>'search',100)||'%'))
SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(page) ORDER BY page.vencimento,page.id) FROM (SELECT * FROM rows ORDER BY vencimento,id OFFSET (page_number-1)*per_page LIMIT per_page) page),'[]'::jsonb),'count',(SELECT count(*) FROM rows),'summary',(SELECT jsonb_build_object('programado',coalesce(sum(valor) FILTER(WHERE status_nota<>'cancelada'),0),'pago',coalesce(sum(pago) FILTER(WHERE status_nota<>'cancelada'),0),'aberto',coalesce(sum(saldo) FILTER(WHERE status_nota<>'cancelada'),0),'atrasado',coalesce(sum(saldo) FILTER(WHERE status_nota<>'cancelada' AND vencimento<today),0),'proximos',coalesce(sum(saldo) FILTER(WHERE status_nota<>'cancelada' AND vencimento BETWEEN today AND today+7),0),'bloqueado',coalesce(sum(saldo) FILTER(WHERE status_nota<>'cancelada' AND NOT liberada_efetiva),0)) FROM rows)) INTO data;RETURN data;END IF;
IF action='order_summary' THEN
SELECT * INTO o FROM public.maintenance_orders WHERE id=(b->>'order_id')::uuid AND company_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'S.OR não encontrada nesta empresa.' USING ERRCODE='42501';END IF;
RETURN jsonb_build_object('order',jsonb_build_object('id',o.id,'numero',o.numero,'orcamento',o.valor_total,'orcamento_status',o.orcamento_status),'faturado',(SELECT coalesce(sum(valor),0) FROM public.maintenance_finance_invoices WHERE company_id=c AND order_id=o.id AND status<>'cancelada'),'pago',(SELECT coalesce(sum(pago),0) FROM public.maintenance_finance_balances WHERE company_id=c AND order_id=o.id AND status_nota<>'cancelada'),'aberto',(SELECT coalesce(sum(saldo),0) FROM public.maintenance_finance_balances WHERE company_id=c AND order_id=o.id AND status_nota<>'cancelada'),'invoices',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'numero',numero,'valor',valor,'status',status) ORDER BY created_at DESC) FROM public.maintenance_finance_invoices WHERE company_id=c AND order_id=o.id),'[]'::jsonb));END IF;
IF action='create' THEN
SELECT * INTO inv FROM public.maintenance_finance_invoices WHERE company_id=c AND request_id=(b->>'request_id')::uuid;IF FOUND THEN RETURN to_jsonb(inv);END IF;
SELECT * INTO o FROM public.maintenance_orders WHERE id=(b->>'order_id')::uuid AND company_id=c FOR UPDATE;IF NOT FOUND OR o.status='cancelada' THEN RAISE EXCEPTION 'Selecione uma S.OR válida desta empresa.';END IF;
SELECT * INTO inv FROM public.maintenance_finance_invoices WHERE company_id=c AND request_id=(b->>'request_id')::uuid;IF FOUND THEN RETURN to_jsonb(inv);END IF;selected:=gen_random_uuid();is_new:=true;
ELSE
SELECT * INTO inv FROM public.maintenance_finance_invoices WHERE id=(b->>'id')::uuid AND company_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'Nota fiscal não encontrada nesta empresa.' USING ERRCODE='42501';END IF;
SELECT * INTO o FROM public.maintenance_orders WHERE id=inv.order_id AND company_id=c FOR UPDATE;
SELECT * INTO inv FROM public.maintenance_finance_invoices WHERE id=inv.id AND company_id=c FOR UPDATE;selected:=inv.id;is_new:=false;
END IF;
IF action='detail' THEN RETURN jsonb_build_object('invoice',to_jsonb(inv),'order',jsonb_build_object('id',o.id,'numero',o.numero,'orcamento',o.valor_total,'orcamento_status',o.orcamento_status,'status',o.status),'summary',(SELECT jsonb_build_object('pago',coalesce(sum(x.pago),0),'saldo',coalesce(sum(x.saldo),0),'faturado_os',coalesce(max(x.faturado_os),0),'liberada',coalesce(bool_and(x.liberada_efetiva),false)) FROM public.maintenance_finance_balances x WHERE x.company_id=c AND x.invoice_id=inv.id),'installments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY parcela) FROM public.maintenance_finance_balances x WHERE company_id=c AND invoice_id=inv.id),'[]'::jsonb),'payments',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at,p.id) FROM public.maintenance_finance_payments p JOIN public.maintenance_finance_installments i ON i.id=p.installment_id WHERE p.company_id=c AND i.invoice_id=inv.id),'[]'::jsonb),'files',coalesce((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.created_at) FROM public.maintenance_finance_files f WHERE f.company_id=c AND f.invoice_id=inv.id),'[]'::jsonb),'audit',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.created_at DESC,a.id) FROM public.maintenance_finance_audit a WHERE a.company_id=c AND a.invoice_id=inv.id),'[]'::jsonb));END IF;
IF action IN ('pay','reverse') THEN SELECT * INTO old_payment FROM public.maintenance_finance_payments WHERE company_id=c AND request_id=(b->>'request_id')::uuid;IF FOUND THEN IF (action='pay' AND old_payment.tipo='pagamento' AND old_payment.installment_id=(b->>'installment_id')::uuid) OR (action='reverse' AND old_payment.tipo='estorno' AND old_payment.reverses_id=(b->>'payment_id')::uuid) THEN RETURN to_jsonb(old_payment);END IF;RAISE EXCEPTION 'Identificador já utilizado em outra operação.';END IF;END IF;
IF NOT is_new AND inv.version IS DISTINCT FROM (b->>'version')::integer THEN RAISE EXCEPTION 'O financeiro foi alterado. Atualize antes de continuar.' USING ERRCODE='40001';END IF;
IF inv.status='cancelada' THEN RAISE EXCEPTION 'Nota cancelada. O histórico não pode ser alterado.';END IF;
IF action IN ('create','update') THEN
IF NOT is_new AND (inv.status<>'conferencia' OR EXISTS(SELECT 1 FROM public.maintenance_finance_payments p JOIN public.maintenance_finance_installments i ON i.id=p.installment_id WHERE i.invoice_id=inv.id)) THEN RAISE EXCEPTION 'Ajuste somente notas em conferência sem histórico de pagamento. Estorne e cancele para corrigir uma nota já movimentada.';END IF;
data:=CASE WHEN is_new THEN NULL ELSE jsonb_build_object('nota',to_jsonb(inv),'parcelas',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.numero) FROM public.maintenance_finance_installments x WHERE x.invoice_id=inv.id)) END;
amount:=maintenance_private.finance_amount(b->>'valor');
IF length(btrim(coalesce(b->>'numero','')))<1 OR length(b->>'numero')>60 OR length(coalesce(b->>'serie',''))>20 OR length(coalesce(b->>'chave_acesso',''))>100 OR length(note)>2000 OR coalesce(b->>'emissao','')='' OR (b->>'emissao')::date>today THEN RAISE EXCEPTION 'Confira número, emissão e dados da nota fiscal.';END IF;
IF jsonb_typeof(b->'parcelas')<>'array' OR jsonb_array_length(b->'parcelas') NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Informe de 1 a 120 parcelas.';END IF;
FOR entry IN SELECT jsonb_array_elements(b->'parcelas') LOOP plan_total:=plan_total+maintenance_private.finance_amount(entry->>'valor');IF coalesce(entry->>'vencimento','')='' OR (entry->>'vencimento')::date<(b->>'emissao')::date THEN RAISE EXCEPTION 'O vencimento não pode ser anterior à emissão.';END IF;END LOOP;
IF plan_total IS DISTINCT FROM amount THEN RAISE EXCEPTION 'A soma exata das parcelas deve ser igual ao valor da nota.';END IF;
IF is_new THEN INSERT INTO public.maintenance_finance_invoices(id,company_id,order_id,partner_id,request_id,numero,serie,chave_acesso,emissao,valor,observacao,created_by) VALUES(selected,c,o.id,o.partner_id,(b->>'request_id')::uuid,btrim(b->>'numero'),btrim(coalesce(b->>'serie','')),btrim(coalesce(b->>'chave_acesso','')),(b->>'emissao')::date,amount,note,auth.uid()) RETURNING * INTO inv;
ELSE UPDATE public.maintenance_finance_invoices SET numero=btrim(b->>'numero'),serie=btrim(coalesce(b->>'serie','')),chave_acesso=btrim(coalesce(b->>'chave_acesso','')),emissao=(b->>'emissao')::date,valor=amount,observacao=note,version=version+1,updated_at=clock_timestamp() WHERE id=inv.id RETURNING * INTO inv;DELETE FROM public.maintenance_finance_installments WHERE invoice_id=inv.id;END IF;
idx:=0;FOR entry IN SELECT jsonb_array_elements(b->'parcelas') LOOP idx:=idx+1;INSERT INTO public.maintenance_finance_installments(company_id,invoice_id,numero,vencimento,valor) VALUES(c,inv.id,idx,(entry->>'vencimento')::date,(entry->>'valor')::numeric);END LOOP;
PERFORM maintenance_private.finance_event(c,inv.id,CASE WHEN is_new THEN 'criacao' ELSE 'edicao' END,'Nota fiscal e parcelas registradas',jsonb_build_object('antes',data,'nota',to_jsonb(inv),'valor',amount,'parcelas',b->'parcelas','orcamento_atual',o.valor_total));RETURN to_jsonb(inv);END IF;
IF action='release' THEN
IF o.orcamento_status<>'aprovado' OR o.aprovado_em IS NULL OR o.status='cancelada' OR inv.partner_id<>o.partner_id THEN RAISE EXCEPTION 'Pagamento exige orçamento aprovado e oficina correspondente à S.OR.';END IF;
SELECT sum(valor) INTO total FROM public.maintenance_finance_invoices WHERE company_id=c AND order_id=o.id AND status<>'cancelada';
IF total>o.valor_total AND length(note)<5 THEN RAISE EXCEPTION 'Faturamento acima do orçamento: justifique a divergência para liberar.';END IF;IF length(note)>2000 THEN RAISE EXCEPTION 'Justificativa muito longa.';END IF;
UPDATE public.maintenance_finance_invoices SET status='liberada',referencia_orcamento=o.valor_total,referencia_aprovacao=o.aprovado_em,referencia_faturado=total,justificativa=note,conferido_por=auth.uid(),conferido_em=clock_timestamp(),updated_at=clock_timestamp(),version=version+1 WHERE id=inv.id RETURNING * INTO inv;
PERFORM maintenance_private.finance_event(c,inv.id,'conferencia','Conferência financeira e liberação registradas',jsonb_build_object('orcamento',o.valor_total,'faturado_os',total,'justificativa',note));RETURN to_jsonb(inv);END IF;
IF action='reopen' THEN IF length(note)<5 THEN RAISE EXCEPTION 'Informe o motivo da reabertura.';END IF;UPDATE public.maintenance_finance_invoices SET status='conferencia',version=version+1,updated_at=clock_timestamp() WHERE id=inv.id RETURNING * INTO inv;PERFORM maintenance_private.finance_event(c,inv.id,'reabertura','Nota devolvida para conferência',jsonb_build_object('motivo',note));RETURN to_jsonb(inv);END IF;
IF action='cancel' THEN
SELECT coalesce(sum(pago),0) INTO paid FROM public.maintenance_finance_balances WHERE invoice_id=inv.id AND company_id=c;
IF paid<>0 THEN RAISE EXCEPTION 'Estorne todos os pagamentos antes de cancelar a nota.';END IF;IF length(note)<5 OR length(note)>2000 THEN RAISE EXCEPTION 'Informe o motivo do cancelamento.';END IF;
UPDATE public.maintenance_finance_invoices SET status='cancelada',motivo_cancelamento=note,version=version+1,updated_at=clock_timestamp() WHERE id=inv.id RETURNING * INTO inv;
PERFORM maintenance_private.finance_event(c,inv.id,'cancelamento','Nota fiscal cancelada com histórico preservado',jsonb_build_object('motivo',note));RETURN to_jsonb(inv);END IF;
IF action='pay' THEN
SELECT * INTO bill FROM public.maintenance_finance_installments WHERE id=(b->>'installment_id')::uuid AND company_id=c AND invoice_id=inv.id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Parcela inválida.';END IF;
IF NOT coalesce((SELECT liberada_efetiva FROM public.maintenance_finance_balances WHERE id=bill.id AND company_id=c),false) THEN RAISE EXCEPTION 'Confira e libere novamente a nota: orçamento, oficina ou faturamento podem ter mudado.';END IF;
amount:=maintenance_private.finance_amount(b->>'valor');SELECT saldo INTO total FROM public.maintenance_finance_balances WHERE id=bill.id AND company_id=c;IF amount>total THEN RAISE EXCEPTION 'Pagamento acima do saldo da parcela.';END IF;
IF coalesce(b->>'data_pagamento','')='' OR (b->>'data_pagamento')::date>today OR b->>'metodo' NOT IN ('pix','boleto','transferencia','dinheiro','cartao','outro') OR b->>'metodo' IS NULL OR length(coalesce(b->>'referencia',''))>120 OR length(note)>2000 THEN RAISE EXCEPTION 'Confira data, método e referência do pagamento.';END IF;
INSERT INTO public.maintenance_finance_payments(company_id,installment_id,request_id,tipo,valor,data_pagamento,metodo,referencia,observacao,created_by) VALUES(c,bill.id,(b->>'request_id')::uuid,'pagamento',amount,(b->>'data_pagamento')::date,b->>'metodo',coalesce(b->>'referencia',''),note,auth.uid()) RETURNING * INTO payment;
UPDATE public.maintenance_finance_invoices SET version=version+1,updated_at=clock_timestamp() WHERE id=inv.id;
PERFORM maintenance_private.finance_event(c,inv.id,'pagamento','Pagamento registrado',jsonb_build_object('payment_id',payment.id,'parcela',bill.numero,'valor',amount,'metodo',payment.metodo,'data',payment.data_pagamento));RETURN to_jsonb(payment);END IF;
IF action='reverse' THEN
SELECT p.* INTO old_payment FROM public.maintenance_finance_payments p JOIN public.maintenance_finance_installments i ON i.id=p.installment_id WHERE p.id=(b->>'payment_id')::uuid AND p.company_id=c AND i.invoice_id=inv.id AND p.tipo='pagamento' FOR UPDATE OF p;
IF NOT FOUND OR EXISTS(SELECT 1 FROM public.maintenance_finance_payments WHERE reverses_id=old_payment.id) THEN RAISE EXCEPTION 'Pagamento não encontrado ou já estornado.';END IF;
IF length(note)<5 OR length(note)>2000 THEN RAISE EXCEPTION 'Informe o motivo do estorno.';END IF;
INSERT INTO public.maintenance_finance_payments(company_id,installment_id,request_id,tipo,valor,data_pagamento,metodo,referencia,observacao,reverses_id,created_by) VALUES(c,old_payment.installment_id,(b->>'request_id')::uuid,'estorno',old_payment.valor,today,old_payment.metodo,old_payment.referencia,note,old_payment.id,auth.uid()) RETURNING * INTO payment;
UPDATE public.maintenance_finance_invoices SET version=version+1,updated_at=clock_timestamp() WHERE id=inv.id;
PERFORM maintenance_private.finance_event(c,inv.id,'estorno','Pagamento estornado sem apagar o histórico',jsonb_build_object('payment_id',old_payment.id,'estorno_id',payment.id,'valor',payment.valor,'motivo',note));RETURN to_jsonb(payment);END IF;
IF action='file_add' THEN
IF b->>'categoria' NOT IN ('nota_fiscal','comprovante','outros') OR b->>'categoria' IS NULL OR NOT maintenance_private.finance_storage_access(b->>'object_path',true) OR split_part(b->>'object_path','/',3)<>inv.id::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='maintenance' AND name=b->>'object_path') OR coalesce(b->>'nome','')='' OR length(b->>'nome')>255 OR b->>'content_type' NOT IN ('application/pdf','image/jpeg','image/png','image/webp') THEN RAISE EXCEPTION 'Arquivo inválido ou fora desta nota.';END IF;
IF nullif(b->>'payment_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.maintenance_finance_payments p JOIN public.maintenance_finance_installments i ON i.id=p.installment_id WHERE p.id=(b->>'payment_id')::uuid AND p.company_id=c AND i.invoice_id=inv.id) THEN RAISE EXCEPTION 'Comprovante não pertence a esta nota.';END IF;
INSERT INTO public.maintenance_finance_files(company_id,invoice_id,payment_id,categoria,object_path,nome,content_type,tamanho_bytes,created_by) VALUES(c,inv.id,nullif(b->>'payment_id','')::uuid,b->>'categoria',b->>'object_path',b->>'nome',b->>'content_type',(b->>'tamanho_bytes')::bigint,auth.uid()) RETURNING * INTO file;
UPDATE public.maintenance_finance_invoices SET version=version+1,updated_at=clock_timestamp() WHERE id=inv.id;
PERFORM maintenance_private.finance_event(c,inv.id,'anexo','Documento financeiro anexado',jsonb_build_object('file_id',file.id,'categoria',file.categoria,'nome',file.nome));RETURN to_jsonb(file);END IF;
RAISE EXCEPTION 'Ação financeira inválida.';
END $$;
REVOKE ALL ON FUNCTION maintenance_private.finance_command(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION maintenance_private.finance_command(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.maintenance_finance_command(target_company uuid,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_private.finance_command(target_company,command,body);$$;
REVOKE ALL ON FUNCTION public.maintenance_finance_command(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.maintenance_finance_command(uuid,text,jsonb) TO authenticated;
COMMIT;
